-- Guarded content-only upgrade: frontend-engineering. Original official criteria preserved.
BEGIN;
CREATE TEMP TABLE legacy_guides(payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO legacy_guides(payload) VALUES ($legacy_payload$[{"slug":"frontend-engineering","task_number":1,"title":"Responsive Landing Page","old_description":"[[AZ]]\nMobil və desktop-da oxunaqlı, əlçatan və responsive məhsul landing page-i hazırla.\n\n[[EN]]\nBuild a readable, accessible, responsive product landing page for mobile and desktop.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nTəcrübə proqramını tanıdan, telefonda və kompüterdə düzgün görünən sadə landing page hazırlayacaqsan. Ziyarətçi proqramın nə olduğunu və müraciət addımını tez anlamalıdır.\n\n## 2. Başlamazdan əvvəl\nHTML elementləri, CSS-in əsasları, brauzerdə səhifə açmaq, VS Code və GitHub-dan istifadə. React/Next.js bilmirsənsə, HTML/CSS ilə başlamaq kifayətdir.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `internship-landing-page` repo-su yarat və VS Code-da aç. Sıfırdan başla.\n2. `index.html`, `style.css` və `README.md` faylları yarat.\n3. Başlıq, qısa tanıtım, 3 üstünlük, proqram mərhələləri və “Müraciət et” düyməsi əlavə et.\n4. Oxunaqlı şrift və 2–3 uyğun rəng seç. Hazır dizaynı olduğu kimi köçürmə.\n5. Səhifəni brauzerdə aç və təxminən 360px mobil, 1280px desktop enində yoxla. Mətn kənara çıxmamalı, düymə rahat görünməlidir.\n6. Klaviatura ilə keçidi və şəkillərin alt mətnini yoxla. Saxta əlaqə məlumatı və işləməyən link qoyma.\n7. README-də səhifəni necə açmağı yaz, screenshot-lar əlavə et və repo-nu GitHub-a göndər.\n\n## 4. Konkret nümunə və izah\nİlk ekran proqramın adını, kimlər üçün olduğunu və “Müraciət et” düyməsini göstərsin. Düymə səhifədəki müraciət bölməsinə keçə bilər; hələ server qurmaq lazım deyil. Telefonda mətn və düymə ekranın enindən çıxmamalıdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işlək HTML/CSS səhifəsi, mobil və desktop screenshot-ları və qısa README.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n360px və 1280px ölçüdə görüntü var. Düymənin keçidi işləyir, klaviatura ilə seçilə bilir və şəkillərin uyğun alt mətni var.\n\n[[EN]]\n## 1. Goal\nBuild a simple internship landing page that works on phones and computers. Visitors should quickly understand the program and find the application action.\n\n## 2. Before you start\nHTML elements, basic CSS, opening a page in a browser, and using VS Code and GitHub. If you do not know React/Next.js, plain HTML/CSS is enough to begin.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `internship-landing-page` and open it in VS Code. Start from scratch.\n2. Create `index.html`, `style.css`, and `README.md`.\n3. Add a heading, short introduction, three benefits, program steps, and an “Apply” button.\n4. Choose a readable font and two or three matching colors. Do not copy a ready-made design unchanged.\n5. Open the page in a browser and test around 360px mobile and 1280px desktop widths. Text must not overflow and the button must remain easy to find.\n6. Check keyboard navigation and image alt text. Do not add fake contact details or broken links.\n7. Document how to open the page, add screenshots, and push the repository to GitHub.\n\n## 4. Concrete example and explanation\nThe first screen shows the program name, audience, and Apply action. The button can link to an application section on the page; no server is required yet. Keep text and controls within a phone viewport.\n\n## 5. What to submit\nYour own GitHub repository link, working HTML/CSS page, mobile and desktop screenshots, and a short README.\n\n## 6. How to check your work\nInclude screenshots at 360px and 1280px. The main action works with a keyboard and images have appropriate alt text.","new_description":"[[AZ]]\nMobil və desktop-da oxunaqlı, əlçatan və responsive məhsul landing page-i hazırla.\n\nPulsuz alətlər: Visual Studio Code, Node.js (free), Vite (free), GitHub Free. Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nBuild a readable, accessible, responsive product landing page for mobile and desktop.\n\nFree tools: Visual Studio Code, Node.js (free), Vite (free), GitHub Free. Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Təcrübə proqramını tanıdan landing səhifədə başlıq, fayda, CTA və footer olsun; 360px və 1440px-də yoxla.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Vite (free)** — https://vite.dev. React/TypeScript starter yarat və brauzerdə lokal UI-ni aç.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / frontend-engineering / task-1` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Vite React layihəsini qur, səhifənin HTML semantik elementlərini düzənlə. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Mobil bir sütun və desktop geniş layout üçün CSS media qaydaları qur. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Klaviatura ilə CTA-ya çatma və kontrast yoxlamasını screenshot-la göstər. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Təcrübə proqramını tanıdan landing səhifədə başlıq, fayda, CTA və footer olsun; 360px və 1440px-də yoxla. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nTəcrübə proqramını tanıdan landing səhifədə başlıq, fayda, CTA və footer olsun; 360px və 1440px-də yoxla.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nTəcrübə proqramını tanıdan, telefonda və kompüterdə düzgün görünən sadə landing page hazırlayacaqsan. Ziyarətçi proqramın nə olduğunu və müraciət addımını tez anlamalıdır.\n\n## 2. Başlamazdan əvvəl\nHTML elementləri, CSS-in əsasları, brauzerdə səhifə açmaq, VS Code və GitHub-dan istifadə. React/Next.js bilmirsənsə, HTML/CSS ilə başlamaq kifayətdir.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `internship-landing-page` repo-su yarat və VS Code-da aç. Sıfırdan başla.\n2. `index.html`, `style.css` və `README.md` faylları yarat.\n3. Başlıq, qısa tanıtım, 3 üstünlük, proqram mərhələləri və “Müraciət et” düyməsi əlavə et.\n4. Oxunaqlı şrift və 2–3 uyğun rəng seç. Hazır dizaynı olduğu kimi köçürmə.\n5. Səhifəni brauzerdə aç və təxminən 360px mobil, 1280px desktop enində yoxla. Mətn kənara çıxmamalı, düymə rahat görünməlidir.\n6. Klaviatura ilə keçidi və şəkillərin alt mətnini yoxla. Saxta əlaqə məlumatı və işləməyən link qoyma.\n7. README-də səhifəni necə açmağı yaz, screenshot-lar əlavə et və repo-nu GitHub-a göndər.\n\n## 4. Konkret nümunə və izah\nİlk ekran proqramın adını, kimlər üçün olduğunu və “Müraciət et” düyməsini göstərsin. Düymə səhifədəki müraciət bölməsinə keçə bilər; hələ server qurmaq lazım deyil. Telefonda mətn və düymə ekranın enindən çıxmamalıdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işlək HTML/CSS səhifəsi, mobil və desktop screenshot-ları və qısa README.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n360px və 1280px ölçüdə görüntü var. Düymənin keçidi işləyir, klaviatura ilə seçilə bilir və şəkillərin uyğun alt mətni var.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Build a landing page with a heading, benefits, CTA and footer tested at 360px and 1440px.\n\n## Free tools and how to start\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Vite (free)** — https://vite.dev. Create a React/TypeScript starter and run the UI locally.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / frontend-engineering / task-1` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Create a Vite React project and semantic page structure. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Implement a one-column mobile and wider desktop layout. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Show keyboard CTA access and a contrast check with screenshots. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Build a landing page with a heading, benefits, CTA and footer tested at 360px and 1440px. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nBuild a landing page with a heading, benefits, CTA and footer tested at 360px and 1440px.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nBuild a simple internship landing page that works on phones and computers. Visitors should quickly understand the program and find the application action.\n\n## 2. Before you start\nHTML elements, basic CSS, opening a page in a browser, and using VS Code and GitHub. If you do not know React/Next.js, plain HTML/CSS is enough to begin.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `internship-landing-page` and open it in VS Code. Start from scratch.\n2. Create `index.html`, `style.css`, and `README.md`.\n3. Add a heading, short introduction, three benefits, program steps, and an “Apply” button.\n4. Choose a readable font and two or three matching colors. Do not copy a ready-made design unchanged.\n5. Open the page in a browser and test around 360px mobile and 1280px desktop widths. Text must not overflow and the button must remain easy to find.\n6. Check keyboard navigation and image alt text. Do not add fake contact details or broken links.\n7. Document how to open the page, add screenshots, and push the repository to GitHub.\n\n## 4. Concrete example and explanation\nThe first screen shows the program name, audience, and Apply action. The button can link to an application section on the page; no server is required yet. Keep text and controls within a phone viewport.\n\n## 5. What to submit\nYour own GitHub repository link, working HTML/CSS page, mobile and desktop screenshots, and a short README.\n\n## 6. How to check your work\nInclude screenshots at 360px and 1280px. The main action works with a keyboard and images have appropriate alt text."},{"slug":"frontend-engineering","task_number":2,"title":"Reusable Component System","old_description":"[[AZ]]\nTəkrar istifadə edilən form, badge və empty-state komponentləri ilə kiçik UI sistem qur.\n\n[[EN]]\nBuild a small UI system with reusable form, badge, and empty-state components.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nDörd təkrar istifadə edilən UI komponenti hazırlayacaqsan: Button, TextField, StatusBadge və EmptyState. Məqsəd görünüşü, davranışı və əlçatanlığı ardıcıl saxlamaqdır.\n\n## 2. Başlamazdan əvvəl\nHTML/CSS, sadə React komponenti və TypeScript props anlayışı. 1-ci tapşırığı HTML ilə etmisənsə, əvvəl React/TypeScript starter qur: məsələn, `npm create vite@latest component-practice -- --template react-ts`, sonra həmin qovluqda `npm install` və `npm run dev`. Node.js versiyan seçilən alətin tələbinə uyğun olsun; quraşdırıcı versiya xətası verirsə onu düzəlt. Yaranan layihəni öz repo-na əlavə et; mövcud React layihən varsa onu davam etdir.\n\n## 3. Addım-addım icra\n1. Tapşırıq 1-də yaratdığın öz repo-nu davam etdir.\n2. Hər komponentin props və variantlarını yaz. Məsələn, Button üçün primary/secondary, loading və disabled.\n3. Rəng, aralıq və şrift dəyərlərini təkrar istifadə edilən token-larda saxla.\n4. TextField üçün görünən label, köməkçi mətn və xətanı düzgün əlaqələndir.\n5. Bütün variantları göstərən demo səhifəsi yarat və ən azı 6 UI testi yaz.\n6. Mövcud test/lint/build əmrlərini yoxla və varsa işlət. README-də quraşdırma və istifadə qaydasını yaz.\n\n## 4. Konkret nümunə və izah\nKomponent eyni qayda ilə bir neçə yerdə işlədilən UI hissəsidir; props ona ötürülən seçimlərdir. Task 1-i HTML/CSS ilə etmisənsə, əvvəl React/TypeScript üçün kiçik starter qur və README-də run əmrini yaz. Button üçün loading zamanı təkrar klik bloklansın.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 4 komponent və TypeScript props-ları, demo screenshot-u, ən azı 6 test və qısa istifadə təlimatı. Xəta təkcə rənglə göstərilməməli, variantlar isə aydın props/token-larla idarə olunmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nButton, TextField, StatusBadge və EmptyState demo-da görünür. Altı test ən azı klik, disabled, loading, label/error əlaqəsi, status mətni və boş vəziyyəti yoxlayır.\n\n[[EN]]\n## 1. Goal\nBuild four reusable UI components: Button, TextField, StatusBadge, and EmptyState. Keep their appearance, behavior, and accessibility consistent.\n\n## 2. Before you start\nBasic HTML/CSS, React components, and TypeScript props. If Task 1 used plain HTML, first create a React/TypeScript starter, for example `npm create vite@latest component-practice -- --template react-ts`, then run `npm install` and `npm run dev` inside that folder. Use a Node.js version supported by the selected tool and resolve any installer version warning. Add it to your repository, or continue your existing React project.\n\n## 3. Step-by-step work\n1. Continue your own repository from Task 1.\n2. Define each component's props and variants, such as primary/secondary, loading, and disabled for Button.\n3. Store reusable colors, spacing, and typography as tokens.\n4. Associate TextField labels, helper text, and errors correctly.\n5. Create a demo page showing every variant and write at least six UI tests.\n6. Check available test/lint/build scripts and run them when present. Document setup and usage in the README.\n\n## 4. Concrete example and explanation\nA component is a reusable UI element; props are its inputs. If Task 1 used HTML/CSS, first set up a small React/TypeScript starter and document its run command. A loading button must block repeated clicks.\n\n## 5. What to submit\nYour own GitHub repository link, four components with TypeScript props, a demo screenshot, at least six tests, and a short usage guide. Errors must not be conveyed by color alone, and variants should use clear props/tokens.\n\n## 6. How to check your work\nShow Button, TextField, StatusBadge, and EmptyState in a demo. Six tests cover click, disabled, loading, label/error association, status text, and empty state.","new_description":"[[AZ]]\nTəkrar istifadə edilən form, badge və empty-state komponentləri ilə kiçik UI sistem qur.\n\nPulsuz alətlər: Visual Studio Code, Node.js (free), Vite (free), GitHub Free. Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nBuild a small UI system with reusable form, badge, and empty-state components.\n\nFree tools: Visual Studio Code, Node.js (free), Vite (free), GitHub Free. Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Button, TextField, StatusBadge və EmptyState komponentləri eyni prop qaydası ilə işləsin.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Vite (free)** — https://vite.dev. React/TypeScript starter yarat və brauzerdə lokal UI-ni aç.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / frontend-engineering / task-2` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Hər komponent üçün TypeScript prop tipi və iki istifadə nümunəsi yaz. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Disabled, loading, error və boş vəziyyətləri ayrıca göstər. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Qısa demo səhifəsində reuse və keyboard focus davranışını test et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Button, TextField, StatusBadge və EmptyState komponentləri eyni prop qaydası ilə işləsin. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nButton, TextField, StatusBadge və EmptyState komponentləri eyni prop qaydası ilə işləsin.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nDörd təkrar istifadə edilən UI komponenti hazırlayacaqsan: Button, TextField, StatusBadge və EmptyState. Məqsəd görünüşü, davranışı və əlçatanlığı ardıcıl saxlamaqdır.\n\n## 2. Başlamazdan əvvəl\nHTML/CSS, sadə React komponenti və TypeScript props anlayışı. 1-ci tapşırığı HTML ilə etmisənsə, əvvəl React/TypeScript starter qur: məsələn, `npm create vite@latest component-practice -- --template react-ts`, sonra həmin qovluqda `npm install` və `npm run dev`. Node.js versiyan seçilən alətin tələbinə uyğun olsun; quraşdırıcı versiya xətası verirsə onu düzəlt. Yaranan layihəni öz repo-na əlavə et; mövcud React layihən varsa onu davam etdir.\n\n## 3. Addım-addım icra\n1. Tapşırıq 1-də yaratdığın öz repo-nu davam etdir.\n2. Hər komponentin props və variantlarını yaz. Məsələn, Button üçün primary/secondary, loading və disabled.\n3. Rəng, aralıq və şrift dəyərlərini təkrar istifadə edilən token-larda saxla.\n4. TextField üçün görünən label, köməkçi mətn və xətanı düzgün əlaqələndir.\n5. Bütün variantları göstərən demo səhifəsi yarat və ən azı 6 UI testi yaz.\n6. Mövcud test/lint/build əmrlərini yoxla və varsa işlət. README-də quraşdırma və istifadə qaydasını yaz.\n\n## 4. Konkret nümunə və izah\nKomponent eyni qayda ilə bir neçə yerdə işlədilən UI hissəsidir; props ona ötürülən seçimlərdir. Task 1-i HTML/CSS ilə etmisənsə, əvvəl React/TypeScript üçün kiçik starter qur və README-də run əmrini yaz. Button üçün loading zamanı təkrar klik bloklansın.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 4 komponent və TypeScript props-ları, demo screenshot-u, ən azı 6 test və qısa istifadə təlimatı. Xəta təkcə rənglə göstərilməməli, variantlar isə aydın props/token-larla idarə olunmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nButton, TextField, StatusBadge və EmptyState demo-da görünür. Altı test ən azı klik, disabled, loading, label/error əlaqəsi, status mətni və boş vəziyyəti yoxlayır.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Implement consistent Button, TextField, StatusBadge and EmptyState components.\n\n## Free tools and how to start\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Vite (free)** — https://vite.dev. Create a React/TypeScript starter and run the UI locally.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / frontend-engineering / task-2` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Define typed props and two usage examples per component. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Show disabled, loading, error and empty states. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Test reuse and keyboard focus in a demo page. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Implement consistent Button, TextField, StatusBadge and EmptyState components. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nImplement consistent Button, TextField, StatusBadge and EmptyState components.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nBuild four reusable UI components: Button, TextField, StatusBadge, and EmptyState. Keep their appearance, behavior, and accessibility consistent.\n\n## 2. Before you start\nBasic HTML/CSS, React components, and TypeScript props. If Task 1 used plain HTML, first create a React/TypeScript starter, for example `npm create vite@latest component-practice -- --template react-ts`, then run `npm install` and `npm run dev` inside that folder. Use a Node.js version supported by the selected tool and resolve any installer version warning. Add it to your repository, or continue your existing React project.\n\n## 3. Step-by-step work\n1. Continue your own repository from Task 1.\n2. Define each component's props and variants, such as primary/secondary, loading, and disabled for Button.\n3. Store reusable colors, spacing, and typography as tokens.\n4. Associate TextField labels, helper text, and errors correctly.\n5. Create a demo page showing every variant and write at least six UI tests.\n6. Check available test/lint/build scripts and run them when present. Document setup and usage in the README.\n\n## 4. Concrete example and explanation\nA component is a reusable UI element; props are its inputs. If Task 1 used HTML/CSS, first set up a small React/TypeScript starter and document its run command. A loading button must block repeated clicks.\n\n## 5. What to submit\nYour own GitHub repository link, four components with TypeScript props, a demo screenshot, at least six tests, and a short usage guide. Errors must not be conveyed by color alone, and variants should use clear props/tokens.\n\n## 6. How to check your work\nShow Button, TextField, StatusBadge, and EmptyState in a demo. Six tests cover click, disabled, loading, label/error association, status text, and empty state."},{"slug":"frontend-engineering","task_number":3,"title":"API-powered Dashboard","old_description":"[[AZ]]\nAPI məlumatı ilə yüklənmə, uğur, boş və xəta vəziyyətləri olan idarəetmə paneli qur.\n\n[[EN]]\nBuild a data-backed dashboard with loading, success, empty, and error states.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nKoordinator panelində müraciət sayını və son müraciətləri göstərəcək dashboard-u mock API-yə bağlayacaqsan. Uğurlu cavab, boş siyahı, giriş xətası və server xətası fərqli göstərilməlidir.\n\n## 2. Başlamazdan əvvəl\nÖz frontend repo-n, React state/effect, TypeScript tipləri, API sorğuları və komponent testlərinin əsasları. Real tələbə məlumatı yox, sintetik test məlumatı işlət.\n\n## 3. Addım-addım icra\n1. Tapşırıq 2-dəki öz repo-nu davam etdir.\n2. Müraciət üçün TypeScript data tipi və mock API cavab formatı yarat.\n3. Dörd ssenari hazırla: 200 və məlumat var, 200 və boş siyahı, 401, 500. Real API açarı tələb olunmayan lokal mock istifadə et.\n4. Loading, success, empty və recoverable error vəziyyətlərini qur.\n5. Refresh/retry düyməsi əlavə et; retry eyni vaxtda təkrarlanan sorğular yaratmasın.\n6. Bu vəziyyətləri test et, screenshot-lar çək və README-ni yenilə.\n\n## 4. Konkret nümunə və izah\nMock API əvvəlcədən seçilən test cavabını qaytarır. `applications` siyahısında ID, status və tarix saxla. 200+boş siyahı üçün “Müraciət yoxdur”, 500 üçün “Yüklənmədi, yenidən cəhd et”, 401 üçün giriş tələb olunduğunu göstər.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işləyən dashboard, mock API adapter-i, dörd vəziyyətin screenshot-u və state/API davranışını yoxlayan testlər. Boş nəticə ilə server xətası ayrı mesajlar göstərməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nLoading, məlumatlı 200, boş 200, 401 və 500 ayrıca yoxlanıb. Refresh təkrar basılanda eyni vaxtda bir sorğu gedir; köhnə cavab yeni nəticəni əvəz etmir.\n\n[[EN]]\n## 1. Goal\nConnect a coordinator dashboard showing application counts and recent applications to a mock API. Success, empty results, authentication failure, and server failure must look different.\n\n## 2. Before you start\nYour own frontend repository, React state/effects, TypeScript types, basic API requests, and component testing. Use synthetic test data, not real student information.\n\n## 3. Step-by-step work\n1. Continue your own repository from Task 2.\n2. Define a TypeScript application type and the mock API response format.\n3. Create four scenarios: 200 with data, 200 with an empty list, 401, and 500. Use a local mock that needs no real API key.\n4. Build loading, success, empty, and recoverable-error states.\n5. Add refresh/retry behavior without allowing duplicate concurrent requests.\n6. Test the states, capture screenshots, and update the README.\n\n## 4. Concrete example and explanation\nA mock API returns a selected test response. Give applications an ID, status, and date. Distinguish 200+empty (“No applications”), 500 (“Could not load; retry”), and 401 (“Sign in required”).\n\n## 5. What to submit\nYour own GitHub repository link, working dashboard, mock API adapter, screenshots of all four states, and tests for API/state behavior. Empty results and server errors must show different messages.\n\n## 6. How to check your work\nTest loading, populated 200, empty 200, 401, and 500. Repeated refresh allows one pending request; stale responses cannot overwrite newer results.","new_description":"[[AZ]]\nAPI məlumatı ilə yüklənmə, uğur, boş və xəta vəziyyətləri olan idarəetmə paneli qur.\n\nPulsuz alətlər: Visual Studio Code, Node.js (free), Vite (free). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nBuild a data-backed dashboard with loading, success, empty, and error states.\n\nFree tools: Visual Studio Code, Node.js (free), Vite (free). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Mock API-dən 5 müraciət göstərən dashboard-da loading, empty, success və 500 error halı olsun.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Vite (free)** — https://vite.dev. React/TypeScript starter yarat və brauzerdə lokal UI-ni aç.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / frontend-engineering / task-3` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Sintetik `applications.json` fixture hazırla, şəxsi məlumat istifadə etmə. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Mock fetch ilə dörd nəticə halını məcburi göstər. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Hər vəziyyət üçün başlıq, status və uyğun yenidən cəhd düyməsi əlavə et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Mock API-dən 5 müraciət göstərən dashboard-da loading, empty, success və 500 error halı olsun. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nMock API-dən 5 müraciət göstərən dashboard-da loading, empty, success və 500 error halı olsun.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nKoordinator panelində müraciət sayını və son müraciətləri göstərəcək dashboard-u mock API-yə bağlayacaqsan. Uğurlu cavab, boş siyahı, giriş xətası və server xətası fərqli göstərilməlidir.\n\n## 2. Başlamazdan əvvəl\nÖz frontend repo-n, React state/effect, TypeScript tipləri, API sorğuları və komponent testlərinin əsasları. Real tələbə məlumatı yox, sintetik test məlumatı işlət.\n\n## 3. Addım-addım icra\n1. Tapşırıq 2-dəki öz repo-nu davam etdir.\n2. Müraciət üçün TypeScript data tipi və mock API cavab formatı yarat.\n3. Dörd ssenari hazırla: 200 və məlumat var, 200 və boş siyahı, 401, 500. Real API açarı tələb olunmayan lokal mock istifadə et.\n4. Loading, success, empty və recoverable error vəziyyətlərini qur.\n5. Refresh/retry düyməsi əlavə et; retry eyni vaxtda təkrarlanan sorğular yaratmasın.\n6. Bu vəziyyətləri test et, screenshot-lar çək və README-ni yenilə.\n\n## 4. Konkret nümunə və izah\nMock API əvvəlcədən seçilən test cavabını qaytarır. `applications` siyahısında ID, status və tarix saxla. 200+boş siyahı üçün “Müraciət yoxdur”, 500 üçün “Yüklənmədi, yenidən cəhd et”, 401 üçün giriş tələb olunduğunu göstər.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işləyən dashboard, mock API adapter-i, dörd vəziyyətin screenshot-u və state/API davranışını yoxlayan testlər. Boş nəticə ilə server xətası ayrı mesajlar göstərməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nLoading, məlumatlı 200, boş 200, 401 və 500 ayrıca yoxlanıb. Refresh təkrar basılanda eyni vaxtda bir sorğu gedir; köhnə cavab yeni nəticəni əvəz etmir.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Create a five-application dashboard with loading, empty, success and server-error states.\n\n## Free tools and how to start\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Vite (free)** — https://vite.dev. Create a React/TypeScript starter and run the UI locally.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / frontend-engineering / task-3` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Create a fictional applications.json fixture without private data. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Use a mocked fetch function to simulate four response states. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Provide clear status and retry UI for each state. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Create a five-application dashboard with loading, empty, success and server-error states. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nCreate a five-application dashboard with loading, empty, success and server-error states.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nConnect a coordinator dashboard showing application counts and recent applications to a mock API. Success, empty results, authentication failure, and server failure must look different.\n\n## 2. Before you start\nYour own frontend repository, React state/effects, TypeScript types, basic API requests, and component testing. Use synthetic test data, not real student information.\n\n## 3. Step-by-step work\n1. Continue your own repository from Task 2.\n2. Define a TypeScript application type and the mock API response format.\n3. Create four scenarios: 200 with data, 200 with an empty list, 401, and 500. Use a local mock that needs no real API key.\n4. Build loading, success, empty, and recoverable-error states.\n5. Add refresh/retry behavior without allowing duplicate concurrent requests.\n6. Test the states, capture screenshots, and update the README.\n\n## 4. Concrete example and explanation\nA mock API returns a selected test response. Give applications an ID, status, and date. Distinguish 200+empty (“No applications”), 500 (“Could not load; retry”), and 401 (“Sign in required”).\n\n## 5. What to submit\nYour own GitHub repository link, working dashboard, mock API adapter, screenshots of all four states, and tests for API/state behavior. Empty results and server errors must show different messages.\n\n## 6. How to check your work\nTest loading, populated 200, empty 200, 401, and 500. Repeated refresh allows one pending request; stale responses cannot overwrite newer results."},{"slug":"frontend-engineering","task_number":4,"title":"Integrated Frontend Project","old_description":"[[AZ]]\nMüraciət idarəetməsi üçün polished frontend-i API, responsive design və testlərlə tamamla.\n\n[[EN]]\nComplete a polished application-management frontend with API integration, responsive design, and tests.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nTələbə müraciət formu və koordinatorun müraciət siyahısını bir-biri ilə uyğun işləyən frontend funksiyası kimi birləşdirəcəksən. Real backend əvəzinə mock API istifadə et.\n\n## 2. Başlamazdan əvvəl\nÖz əvvəlki tapşırıqlarındakı komponentlər, form validation, filter/pagination, API state-ləri, responsive dizayn və testlərin əsasları. Real şəxsi məlumat və production açarları istifadə etmə.\n\n## 3. Addım-addım icra\n1. Tapşırıq 1–3-dəki öz repo-nu davam etdir. Ayrı repo-lardadırsa, birini əsas layihə seç və digər kodu necə birləşdirdiyini README-də qeyd et.\n2. İki axın qur: tələbə müraciət formu və koordinatorun müraciət siyahısı/detail görünüşü.\n3. Form validation; siyahı üçün filter, pagination, loading, empty və error state-ləri əlavə et.\n4. Submit iki dəfə basıldıqda dublikat yaratma. Siyahı/detail məlumatları uyğun qalsın.\n5. Mobil görünüşü, keyboard navigation və error state-ləri yoxla. Unit/UI testləri əlavə et.\n6. Mövcud lint/test/build əmrlərini yoxla, təmiz quraşdırma sınağı et və məlum məhdudiyyətləri yaz.\n\n## 4. Konkret nümunə və izah\nTələbə uydurma form göndərir → mock yaddaşda müraciət yaranır → koordinator siyahısında görünür → detal eyni ID-ni göstərir. Mock məlumat brauzer yenilənəndə sıfırlanırsa bunu qeyd et. Bu inteqrasiya mərhələsidir; yekun təhvil 10-cu tapşırıqda olacaq.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işlək frontend feature, mock API, testlər, mobil/desktop screenshot-lar və README. Təkrar submit dublikat yaratmamalı, siyahı ilə detail uyğun qalmalı, empty/error/mobile hallar yoxlanılmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nFormdan yaradılmış qeyd siyahı və detalda uyğun görünür. İkiqat klik bir qeyd yaradır; uğursuz göndərmə yazılmış məlumatı silmir. Mobil və klaviatura axını yoxlanıb.\n\n[[EN]]\n## 1. Goal\nCombine a student application form and a coordinator application list into one consistent frontend feature. Use a mock API instead of a real backend.\n\n## 2. Before you start\nYour own components from earlier tasks, form validation, filtering/pagination, API states, responsive design, and basic testing. Do not use real personal data or production credentials.\n\n## 3. Step-by-step work\n1. Continue your own repository from Tasks 1–3. If those tasks are in separate repositories, choose one as the main project and document how you combine the code.\n2. Build two flows: a student application form and a coordinator application list/detail view.\n3. Add form validation and filter, pagination, loading, empty, and error states to the list.\n4. Prevent duplicate submissions and keep list/detail data consistent.\n5. Check mobile layout, keyboard navigation, and error states. Add unit/UI tests.\n6. Check available lint/test/build commands, test a clean setup, and document known limitations.\n\n## 4. Concrete example and explanation\nA fictional form submission creates a mock record, appears in the coordinator list, and opens a detail with the same ID. Document whether refresh resets mock data. Final handoff is Task 10.\n\n## 5. What to submit\nYour own GitHub repository link, working frontend feature, mock API, tests, mobile/desktop screenshots, and README. Repeated submission must not create duplicates, list/detail must stay consistent, and empty/error/mobile cases must be tested.\n\n## 6. How to check your work\nA submitted record matches list/detail views. Double-click creates one record; failed submission retains inputs. Verify mobile and keyboard flows.","new_description":"[[AZ]]\nMüraciət idarəetməsi üçün polished frontend-i API, responsive design və testlərlə tamamla.\n\nPulsuz alətlər: Visual Studio Code, Node.js (free), Vite (free), Vitest (open source), GitHub Free. Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nComplete a polished application-management frontend with API integration, responsive design, and tests.\n\nFree tools: Visual Studio Code, Node.js (free), Vite (free), Vitest (open source), GitHub Free. Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Müraciət formu ilə admin siyahısını bir lokal demo-da birləşdir və backend-i mock saxla.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Vite (free)** — https://vite.dev. React/TypeScript starter yarat və brauzerdə lokal UI-ni aç.\n- **Vitest (open source)** — https://vitest.dev. UI və ya utility testlərini sintetik fixture-lərlə lokal işlət.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / frontend-engineering / task-4` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Əvvəlki komponent, form və mock data hissələrini bir repository-də birləşdir. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Göndərilən müraciətin siyahıda görünməsini lokal state ilə simulyasiya et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Mobil və desktop axınını testlə, mock data istifadə etdiyini README-də bildir. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Müraciət formu ilə admin siyahısını bir lokal demo-da birləşdir və backend-i mock saxla. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nMüraciət formu ilə admin siyahısını bir lokal demo-da birləşdir və backend-i mock saxla.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nTələbə müraciət formu və koordinatorun müraciət siyahısını bir-biri ilə uyğun işləyən frontend funksiyası kimi birləşdirəcəksən. Real backend əvəzinə mock API istifadə et.\n\n## 2. Başlamazdan əvvəl\nÖz əvvəlki tapşırıqlarındakı komponentlər, form validation, filter/pagination, API state-ləri, responsive dizayn və testlərin əsasları. Real şəxsi məlumat və production açarları istifadə etmə.\n\n## 3. Addım-addım icra\n1. Tapşırıq 1–3-dəki öz repo-nu davam etdir. Ayrı repo-lardadırsa, birini əsas layihə seç və digər kodu necə birləşdirdiyini README-də qeyd et.\n2. İki axın qur: tələbə müraciət formu və koordinatorun müraciət siyahısı/detail görünüşü.\n3. Form validation; siyahı üçün filter, pagination, loading, empty və error state-ləri əlavə et.\n4. Submit iki dəfə basıldıqda dublikat yaratma. Siyahı/detail məlumatları uyğun qalsın.\n5. Mobil görünüşü, keyboard navigation və error state-ləri yoxla. Unit/UI testləri əlavə et.\n6. Mövcud lint/test/build əmrlərini yoxla, təmiz quraşdırma sınağı et və məlum məhdudiyyətləri yaz.\n\n## 4. Konkret nümunə və izah\nTələbə uydurma form göndərir → mock yaddaşda müraciət yaranır → koordinator siyahısında görünür → detal eyni ID-ni göstərir. Mock məlumat brauzer yenilənəndə sıfırlanırsa bunu qeyd et. Bu inteqrasiya mərhələsidir; yekun təhvil 10-cu tapşırıqda olacaq.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işlək frontend feature, mock API, testlər, mobil/desktop screenshot-lar və README. Təkrar submit dublikat yaratmamalı, siyahı ilə detail uyğun qalmalı, empty/error/mobile hallar yoxlanılmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nFormdan yaradılmış qeyd siyahı və detalda uyğun görünür. İkiqat klik bir qeyd yaradır; uğursuz göndərmə yazılmış məlumatı silmir. Mobil və klaviatura axını yoxlanıb.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Connect a fictional application form and coordinator list using a mock backend.\n\n## Free tools and how to start\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Vite (free)** — https://vite.dev. Create a React/TypeScript starter and run the UI locally.\n- **Vitest (open source)** — https://vitest.dev. Run UI and utility tests against fictional fixtures locally.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / frontend-engineering / task-4` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Combine earlier components, forms and mock fixtures in one repository. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Simulate a submitted application appearing in the list via local state. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Test mobile/desktop flows and disclose mocked data in README. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Connect a fictional application form and coordinator list using a mock backend. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nConnect a fictional application form and coordinator list using a mock backend.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nCombine a student application form and a coordinator application list into one consistent frontend feature. Use a mock API instead of a real backend.\n\n## 2. Before you start\nYour own components from earlier tasks, form validation, filtering/pagination, API states, responsive design, and basic testing. Do not use real personal data or production credentials.\n\n## 3. Step-by-step work\n1. Continue your own repository from Tasks 1–3. If those tasks are in separate repositories, choose one as the main project and document how you combine the code.\n2. Build two flows: a student application form and a coordinator application list/detail view.\n3. Add form validation and filter, pagination, loading, empty, and error states to the list.\n4. Prevent duplicate submissions and keep list/detail data consistent.\n5. Check mobile layout, keyboard navigation, and error states. Add unit/UI tests.\n6. Check available lint/test/build commands, test a clean setup, and document known limitations.\n\n## 4. Concrete example and explanation\nA fictional form submission creates a mock record, appears in the coordinator list, and opens a detail with the same ID. Document whether refresh resets mock data. Final handoff is Task 10.\n\n## 5. What to submit\nYour own GitHub repository link, working frontend feature, mock API, tests, mobile/desktop screenshots, and README. Repeated submission must not create duplicates, list/detail must stay consistent, and empty/error/mobile cases must be tested.\n\n## 6. How to check your work\nA submitted record matches list/detail views. Double-click creates one record; failed submission retains inputs. Verify mobile and keyboard flows."},{"slug":"frontend-engineering","task_number":5,"title":"Accessible Form Flow","old_description":"[[AZ]]\nMüraciət formunu label, inline validation və aydın uğur/xəta axını ilə tamamla.\n\n[[EN]]\nBuild an application form with labels, inline validation, and clear success/error flows.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nMotivasiya, təcrübə və portfolio məlumatlarını itirmədən təqdim etməyə imkan verən əlçatan form hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz frontend layihən, controlled form input-ları, validation və async request anlayışı. Submit üçün lokal mock endpoint kifayətdir.\n\n## 3. Addım-addım icra\n1. Öz əvvəlki frontend repo-nu davam etdir.\n2. Məcburi motivasiya sahəsi, optional portfolio URL-i və mətn limitləri əlavə et.\n3. Hər input-a label və köməkçi mətn ver; xətanı aid olduğu sahə ilə əlaqələndir.\n4. Submit zamanı loading/disabled, success, server error və network failure vəziyyətlərini göstər.\n5. Xətadan sonra daxil edilmiş məlumatı saxla və təhlükəsiz retry təmin et.\n6. Keyboard-only istifadəni yoxla və success, invalid input, server error, network failure üçün test yaz.\n\n## 4. Konkret nümunə və izah\nMotivasiya üçün, məsələn, 100–1000 simvol aralığı seç və label yanında yaz. Portfolio boş ola bilər, doludursa URL formatını yoxla. Server xətasında sahələri boşaltma; eyni məlumatla təkrar göndərmə təklif et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, form komponenti və validation qaydaları, dörd ssenari üçün testlər, mobil screenshot və accessibility checklist. Double-click dublikat yaratmamalı, xəta təkcə rənglə göstərilməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nUğur, səhv giriş, server xətası və şəbəkə xətası sınaqları keçir. Xəta mətnlə izah edilir və input-la əlaqəlidir; pending zamanı ikiqat göndərmə yoxdur.\n\n[[EN]]\n## 1. Goal\nBuild an accessible form for motivation, experience, and portfolio details without losing user input.\n\n## 2. Before you start\nYour own frontend project, controlled form inputs, validation, and asynchronous requests. A local mock endpoint is sufficient.\n\n## 3. Step-by-step work\n1. Continue your own frontend repository.\n2. Add a required motivation field, optional portfolio URL, and text-length limits.\n3. Give each input a label and helper text; associate errors with their fields.\n4. Show loading/disabled, success, server-error, and network-failure states.\n5. Preserve entered data after a failed response and provide a safe retry.\n6. Check keyboard-only use and test success, invalid input, server error, and network failure.\n\n## 4. Concrete example and explanation\nFor example, define motivation as 100–1000 characters and display that rule. Portfolio is optional, but a supplied value must be a URL. Keep inputs after server failure and offer a retry.\n\n## 5. What to submit\nYour own GitHub repository link, form component and validation rules, tests for four scenarios, a mobile screenshot, and an accessibility checklist. Double-clicking must not create duplicates, and errors must not rely on color alone.\n\n## 6. How to check your work\nPass success, invalid-input, server-error, and network-error tests. Errors are textual and associated with fields; no duplicate submission while pending.","new_description":"[[AZ]]\nMüraciət formunu label, inline validation və aydın uğur/xəta axını ilə tamamla.\n\nPulsuz alətlər: Visual Studio Code, Node.js (free), Vite (free). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nBuild an application form with labels, inline validation, and clear success/error flows.\n\nFree tools: Visual Studio Code, Node.js (free), Vite (free). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Email, motivasiya və portfolio sahələrində label, field error və submit nəticəsi göstər.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Vite (free)** — https://vite.dev. React/TypeScript starter yarat və brauzerdə lokal UI-ni aç.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / frontend-engineering / task-5` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Form sahələrini HTML label ilə bağla, boş və yanlış email yoxla. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Səhv mesajını konkret input altında göstər, focus-un düzgün keçməsini yoxla. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Girişlərin saxlanması və uğurlu submit maketini test et; real məlumat tələb etmə. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Email, motivasiya və portfolio sahələrində label, field error və submit nəticəsi göstər. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nEmail, motivasiya və portfolio sahələrində label, field error və submit nəticəsi göstər.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nMotivasiya, təcrübə və portfolio məlumatlarını itirmədən təqdim etməyə imkan verən əlçatan form hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz frontend layihən, controlled form input-ları, validation və async request anlayışı. Submit üçün lokal mock endpoint kifayətdir.\n\n## 3. Addım-addım icra\n1. Öz əvvəlki frontend repo-nu davam etdir.\n2. Məcburi motivasiya sahəsi, optional portfolio URL-i və mətn limitləri əlavə et.\n3. Hər input-a label və köməkçi mətn ver; xətanı aid olduğu sahə ilə əlaqələndir.\n4. Submit zamanı loading/disabled, success, server error və network failure vəziyyətlərini göstər.\n5. Xətadan sonra daxil edilmiş məlumatı saxla və təhlükəsiz retry təmin et.\n6. Keyboard-only istifadəni yoxla və success, invalid input, server error, network failure üçün test yaz.\n\n## 4. Konkret nümunə və izah\nMotivasiya üçün, məsələn, 100–1000 simvol aralığı seç və label yanında yaz. Portfolio boş ola bilər, doludursa URL formatını yoxla. Server xətasında sahələri boşaltma; eyni məlumatla təkrar göndərmə təklif et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, form komponenti və validation qaydaları, dörd ssenari üçün testlər, mobil screenshot və accessibility checklist. Double-click dublikat yaratmamalı, xəta təkcə rənglə göstərilməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nUğur, səhv giriş, server xətası və şəbəkə xətası sınaqları keçir. Xəta mətnlə izah edilir və input-la əlaqəlidir; pending zamanı ikiqat göndərmə yoxdur.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Build a form with accessible email, motivation and portfolio fields.\n\n## Free tools and how to start\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Vite (free)** — https://vite.dev. Create a React/TypeScript starter and run the UI locally.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / frontend-engineering / task-5` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Associate labels, validate required fields and invalid email formats. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Display helpful inline errors and check keyboard focus. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Test state preservation and a mock success result with fictional data. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Build a form with accessible email, motivation and portfolio fields. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nBuild a form with accessible email, motivation and portfolio fields.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nBuild an accessible form for motivation, experience, and portfolio details without losing user input.\n\n## 2. Before you start\nYour own frontend project, controlled form inputs, validation, and asynchronous requests. A local mock endpoint is sufficient.\n\n## 3. Step-by-step work\n1. Continue your own frontend repository.\n2. Add a required motivation field, optional portfolio URL, and text-length limits.\n3. Give each input a label and helper text; associate errors with their fields.\n4. Show loading/disabled, success, server-error, and network-failure states.\n5. Preserve entered data after a failed response and provide a safe retry.\n6. Check keyboard-only use and test success, invalid input, server error, and network failure.\n\n## 4. Concrete example and explanation\nFor example, define motivation as 100–1000 characters and display that rule. Portfolio is optional, but a supplied value must be a URL. Keep inputs after server failure and offer a retry.\n\n## 5. What to submit\nYour own GitHub repository link, form component and validation rules, tests for four scenarios, a mobile screenshot, and an accessibility checklist. Double-clicking must not create duplicates, and errors must not rely on color alone.\n\n## 6. How to check your work\nPass success, invalid-input, server-error, and network-error tests. Errors are textual and associated with fields; no duplicate submission while pending."},{"slug":"frontend-engineering","task_number":6,"title":"State Management","old_description":"[[AZ]]\nDashboard filter və müraciət formu state-ini proqnozlaşdırılan, test edilən qaydada idarə et.\n\n[[EN]]\nManage dashboard-filter and application-form state predictably and testably.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nDashboard-da filter, axtarış və səhifələmə vəziyyətlərini idarə edəcəksən. Formun yazılmamış, göndərilən və uğurlu vəziyyətləri də aydın olmalıdır.\n\n## 2. Başlamazdan əvvəl\nÖz frontend repo-n, React state, URL query parametrləri və TypeScript əsasları. Tapşırıq 3-dəki mock müraciət məlumatlarından istifadə edə bilərsən.\n\n## 3. Addım-addım icra\n1. Öz layihəni davam etdir.\n2. Status filter, search query və page state əlavə et. Hansının URL-də, hansının komponentdə qalacağını izah et.\n3. Filter dəyişəndə page-i 1-ə qaytar; URL-də saxlanan filter-lər refresh-dən sonra bərpa olunsun.\n4. Eyni məlumatı iki state-də saxlamamaq üçün derived state/selector istifadə et.\n5. Form üçün dirty, submitting və success keçidlərini qur.\n6. Filter, axtarış, səhifələmə, form keçidləri, refresh və back düyməsini test et.\n\n## 4. Konkret nümunə və izah\n`?status=pending&page=2` kimi URL filtr/səhifəni paylaşmağa imkan verir. Yeni filtr seçiləndə page=1 olsun. “Dirty” form istifadəçinin dəyişdirdiyi, amma hələ göndərmədiyi formdur; filtr dəyişmək həmin mətni silməməlidir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, state diagramı, işlək kod, testlər və refresh/back demo-su. URL filter-ləri refresh-dən sonra bərpa olunmalı, əlaqəsiz form məlumatı itməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nRefresh URL vəziyyətini bərpa edir, Back əvvəlki filtri qaytarır. Axtarış+status birlikdə işləyir; formun dirty/submitting/success keçidləri ayrıca test olunub.\n\n[[EN]]\n## 1. Goal\nManage filtering, searching, and pagination on the dashboard while keeping form states predictable.\n\n## 2. Before you start\nYour own frontend repository, React state, URL query parameters, and basic TypeScript. You may reuse the mock application data from Task 3.\n\n## 3. Step-by-step work\n1. Continue your own project.\n2. Add status filter, search query, and page state. Explain which values belong in the URL and which remain local.\n3. Reset the page to 1 when filters change and restore URL-based filters after refresh.\n4. Use derived values/selectors rather than storing the same data in multiple states.\n5. Model dirty, submitting, and success transitions for the form.\n6. Test filters, search, pagination, form transitions, refresh, and the back button.\n\n## 4. Concrete example and explanation\nA URL such as `?status=pending&page=2` preserves shareable filters/pages. Reset to page 1 after changing filters. A dirty form has unsent user edits; filtering must not erase them.\n\n## 5. What to submit\nYour own GitHub repository link, state diagram, implementation, tests, and a refresh/back demo. URL filters must restore after refresh, and unrelated form input must not disappear.\n\n## 6. How to check your work\nRefresh restores URL state and Back restores prior filters. Test combined search/status plus separate dirty/submitting/success form transitions.","new_description":"[[AZ]]\nDashboard filter və müraciət formu state-ini proqnozlaşdırılan, test edilən qaydada idarə et.\n\nPulsuz alətlər: Visual Studio Code, Node.js (free), Vite (free), Vitest (open source). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nManage dashboard-filter and application-form state predictably and testably.\n\nFree tools: Visual Studio Code, Node.js (free), Vite (free), Vitest (open source). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Status filter, axtarış və cari səhifə dəyişəndə siyahı uyğun yenilənsin.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Vite (free)** — https://vite.dev. React/TypeScript starter yarat və brauzerdə lokal UI-ni aç.\n- **Vitest (open source)** — https://vitest.dev. UI və ya utility testlərini sintetik fixture-lərlə lokal işlət.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / frontend-engineering / task-6` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. State modelini useState/useReducer ilə yaz və asılılıqları qeyd et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Filter dəyişəndə səhifəni 1-ə qaytaran qayda qur. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Boş nəticə və ardıcıl kliklər üçün 3 test ssenarisi yaz. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Status filter, axtarış və cari səhifə dəyişəndə siyahı uyğun yenilənsin. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nStatus filter, axtarış və cari səhifə dəyişəndə siyahı uyğun yenilənsin.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nDashboard-da filter, axtarış və səhifələmə vəziyyətlərini idarə edəcəksən. Formun yazılmamış, göndərilən və uğurlu vəziyyətləri də aydın olmalıdır.\n\n## 2. Başlamazdan əvvəl\nÖz frontend repo-n, React state, URL query parametrləri və TypeScript əsasları. Tapşırıq 3-dəki mock müraciət məlumatlarından istifadə edə bilərsən.\n\n## 3. Addım-addım icra\n1. Öz layihəni davam etdir.\n2. Status filter, search query və page state əlavə et. Hansının URL-də, hansının komponentdə qalacağını izah et.\n3. Filter dəyişəndə page-i 1-ə qaytar; URL-də saxlanan filter-lər refresh-dən sonra bərpa olunsun.\n4. Eyni məlumatı iki state-də saxlamamaq üçün derived state/selector istifadə et.\n5. Form üçün dirty, submitting və success keçidlərini qur.\n6. Filter, axtarış, səhifələmə, form keçidləri, refresh və back düyməsini test et.\n\n## 4. Konkret nümunə və izah\n`?status=pending&page=2` kimi URL filtr/səhifəni paylaşmağa imkan verir. Yeni filtr seçiləndə page=1 olsun. “Dirty” form istifadəçinin dəyişdirdiyi, amma hələ göndərmədiyi formdur; filtr dəyişmək həmin mətni silməməlidir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, state diagramı, işlək kod, testlər və refresh/back demo-su. URL filter-ləri refresh-dən sonra bərpa olunmalı, əlaqəsiz form məlumatı itməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nRefresh URL vəziyyətini bərpa edir, Back əvvəlki filtri qaytarır. Axtarış+status birlikdə işləyir; formun dirty/submitting/success keçidləri ayrıca test olunub.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Make filters, search and pagination update a task list predictably.\n\n## Free tools and how to start\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Vite (free)** — https://vite.dev. Create a React/TypeScript starter and run the UI locally.\n- **Vitest (open source)** — https://vitest.dev. Run UI and utility tests against fictional fixtures locally.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / frontend-engineering / task-6` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Define state with useState/useReducer and document dependencies. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Reset pagination to page one whenever a filter changes. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Test empty results and repeated interactions. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Make filters, search and pagination update a task list predictably. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nMake filters, search and pagination update a task list predictably.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nManage filtering, searching, and pagination on the dashboard while keeping form states predictable.\n\n## 2. Before you start\nYour own frontend repository, React state, URL query parameters, and basic TypeScript. You may reuse the mock application data from Task 3.\n\n## 3. Step-by-step work\n1. Continue your own project.\n2. Add status filter, search query, and page state. Explain which values belong in the URL and which remain local.\n3. Reset the page to 1 when filters change and restore URL-based filters after refresh.\n4. Use derived values/selectors rather than storing the same data in multiple states.\n5. Model dirty, submitting, and success transitions for the form.\n6. Test filters, search, pagination, form transitions, refresh, and the back button.\n\n## 4. Concrete example and explanation\nA URL such as `?status=pending&page=2` preserves shareable filters/pages. Reset to page 1 after changing filters. A dirty form has unsent user edits; filtering must not erase them.\n\n## 5. What to submit\nYour own GitHub repository link, state diagram, implementation, tests, and a refresh/back demo. URL filters must restore after refresh, and unrelated form input must not disappear.\n\n## 6. How to check your work\nRefresh restores URL state and Back restores prior filters. Test combined search/status plus separate dirty/submitting/success form transitions."},{"slug":"frontend-engineering","task_number":7,"title":"Performance Pass","old_description":"[[AZ]]\nFrontend yüklənməsini ölç, ən bahalı bottleneck-i müəyyən et və sübutla optimallaşdır.\n\n[[EN]]\nMeasure frontend loading, identify the largest bottleneck, and optimize it with evidence.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nFrontend səhifəsinin performansını ölçəcək, sonra sübutla təsdiqlənən bir problemi düzəldəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz frontend repo-n, production build anlayışı və brauzerin Developer Tools bölməsindən istifadə. Ölçmələr eyni şəraitdə aparılmalıdır.\n\n## 3. Addım-addım icra\n1. Öz dashboard route-unu seç və layihəni davam etdir.\n2. Eyni build və network şəraitində başlanğıc ölçməsini götür: performance trace və bundle ölçüsü.\n3. Böyük dependency, şəkil ölçüsü, bloklayan request və lazımsız renderləri araşdır.\n4. Ən vacib görünən bir problemi seç və bir dəyişiklik et.\n5. Eyni şəraitdə yenidən ölç və əvvəl/sonra nəticələrini cədvəldə müqayisə et.\n6. Yaxşılaşma yoxdursa, bunu dürüst qeyd et və növbəti sınağı izah et.\n\n## 4. Konkret nümunə və izah\nMəsələn, production səhifəsində çox böyük şəkil yüklənməni gecikdirirsə, əvvəl ölçünü və yüklənmə vaxtını qeyd et, şəkli kiçilt və eyni şərtlərdə yenidən ölç. Bir anda çox dəyişiklik etmə ki, nəticənin səbəbi bilinsin.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, əvvəl/sonra ölçülər, bir optimallaşdırma diff-i və nəticə hesabatı. Müqayisə eyni şəraitdə olmalı, istifadəçi davranışı pozulmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nEyni cihaz/viewport, network məhdudiyyəti və build rejimində ən azı 3 ölçmənin nəticəsi göstərilib. Yalnız daha əlverişli nəticə seçilməyib; əsas funksiyalar işləyir.\n\n[[EN]]\n## 1. Goal\nMeasure frontend performance and fix one issue supported by evidence.\n\n## 2. Before you start\nYour own frontend repository, production-build basics, and browser Developer Tools. Keep measurement conditions consistent.\n\n## 3. Step-by-step work\n1. Choose your dashboard route and continue your project.\n2. Capture baseline performance and bundle size under consistent build/network conditions.\n3. Investigate large dependencies, image sizes, blocking requests, and unnecessary renders.\n4. Choose the most impactful likely issue and make one change.\n5. Measure again under the same conditions and compare before/after results in a table.\n6. If performance did not improve, report that honestly and explain the next experiment.\n\n## 4. Concrete example and explanation\nIf a large image delays a production page, record its size and loading time, resize it, and measure under the same conditions. Change one thing so the effect can be attributed.\n\n## 5. What to submit\nYour own GitHub repository link, before/after measurements, one optimization diff, and a report showing its effect. Use consistent conditions and preserve user behavior.\n\n## 6. How to check your work\nShow at least three measurements with consistent device/viewport, network, and build mode. Do not cherry-pick the best run; preserve functionality.","new_description":"[[AZ]]\nFrontend yüklənməsini ölç, ən bahalı bottleneck-i müəyyən et və sübutla optimallaşdır.\n\nPulsuz alətlər: Chrome DevTools / Lighthouse, Visual Studio Code, Node.js (free). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nMeasure frontend loading, identify the largest bottleneck, and optimize it with evidence.\n\nFree tools: Chrome DevTools / Lighthouse, Visual Studio Code, Node.js (free). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Lighthouse ilə mobil ölçüdə eyni səhifəni əvvəl/sonra ölç; əsas problemi düzəlt.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Chrome DevTools / Lighthouse** — https://developer.chrome.com/docs/lighthouse. Brauzerdə mobil responsive və performans ölçmələrini ödənişsiz apar.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / frontend-engineering / task-7` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Eyni cihaz/şəbəkə şəraitində iki ilkin ölçü apar. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Ən baha şəkil, JS bundle və ya font problemini tapıb düzəlt. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Sonra yenidən ölçərək fərqi və testin qeyri-dəqiqliyini qeyd et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Lighthouse ilə mobil ölçüdə eyni səhifəni əvvəl/sonra ölç; əsas problemi düzəlt. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nLighthouse ilə mobil ölçüdə eyni səhifəni əvvəl/sonra ölç; əsas problemi düzəlt.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nFrontend səhifəsinin performansını ölçəcək, sonra sübutla təsdiqlənən bir problemi düzəldəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz frontend repo-n, production build anlayışı və brauzerin Developer Tools bölməsindən istifadə. Ölçmələr eyni şəraitdə aparılmalıdır.\n\n## 3. Addım-addım icra\n1. Öz dashboard route-unu seç və layihəni davam etdir.\n2. Eyni build və network şəraitində başlanğıc ölçməsini götür: performance trace və bundle ölçüsü.\n3. Böyük dependency, şəkil ölçüsü, bloklayan request və lazımsız renderləri araşdır.\n4. Ən vacib görünən bir problemi seç və bir dəyişiklik et.\n5. Eyni şəraitdə yenidən ölç və əvvəl/sonra nəticələrini cədvəldə müqayisə et.\n6. Yaxşılaşma yoxdursa, bunu dürüst qeyd et və növbəti sınağı izah et.\n\n## 4. Konkret nümunə və izah\nMəsələn, production səhifəsində çox böyük şəkil yüklənməni gecikdirirsə, əvvəl ölçünü və yüklənmə vaxtını qeyd et, şəkli kiçilt və eyni şərtlərdə yenidən ölç. Bir anda çox dəyişiklik etmə ki, nəticənin səbəbi bilinsin.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, əvvəl/sonra ölçülər, bir optimallaşdırma diff-i və nəticə hesabatı. Müqayisə eyni şəraitdə olmalı, istifadəçi davranışı pozulmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nEyni cihaz/viewport, network məhdudiyyəti və build rejimində ən azı 3 ölçmənin nəticəsi göstərilib. Yalnız daha əlverişli nəticə seçilməyib; əsas funksiyalar işləyir.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Measure a page before/after one performance optimization with Chrome Lighthouse.\n\n## Free tools and how to start\n- **Chrome DevTools / Lighthouse** — https://developer.chrome.com/docs/lighthouse. Use free browser tools to inspect responsive layout and performance.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / frontend-engineering / task-7` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Capture baseline Lighthouse runs under similar conditions. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Optimize one expensive image, JavaScript bundle or font issue. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Re-measure and document the change and measurement variance. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Measure a page before/after one performance optimization with Chrome Lighthouse. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nMeasure a page before/after one performance optimization with Chrome Lighthouse.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nMeasure frontend performance and fix one issue supported by evidence.\n\n## 2. Before you start\nYour own frontend repository, production-build basics, and browser Developer Tools. Keep measurement conditions consistent.\n\n## 3. Step-by-step work\n1. Choose your dashboard route and continue your project.\n2. Capture baseline performance and bundle size under consistent build/network conditions.\n3. Investigate large dependencies, image sizes, blocking requests, and unnecessary renders.\n4. Choose the most impactful likely issue and make one change.\n5. Measure again under the same conditions and compare before/after results in a table.\n6. If performance did not improve, report that honestly and explain the next experiment.\n\n## 4. Concrete example and explanation\nIf a large image delays a production page, record its size and loading time, resize it, and measure under the same conditions. Change one thing so the effect can be attributed.\n\n## 5. What to submit\nYour own GitHub repository link, before/after measurements, one optimization diff, and a report showing its effect. Use consistent conditions and preserve user behavior.\n\n## 6. How to check your work\nShow at least three measurements with consistent device/viewport, network, and build mode. Do not cherry-pick the best run; preserve functionality."},{"slug":"frontend-engineering","task_number":8,"title":"Frontend Testing","old_description":"[[AZ]]\nComponent, user interaction və əsas error state-lər üçün etibarlı frontend testləri yaz.\n\n[[EN]]\nWrite reliable frontend tests for components, user interactions, and error states.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nMüraciət formu və koordinator dashboard-unda əsas istifadəçi davranışlarını testlərlə qoruyacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz frontend layihən, React Testing Library və layihədə istifadə olunan test aləti (Vitest/Jest). Mövcud test setup-u varsa, onu davam etdir.\n\n## 3. Addım-addım icra\n1. Öz repo-nu davam etdir.\n2. Əsas uğurlu axını və ən azı 4 xəta/kənar vəziyyəti seç.\n3. Elementləri label, role və görünən mətnlə tap; class adlarına həddindən artıq bağlanma.\n4. API sorğularını mock et və loading, retry, invalid input və server error hallarını yoxla.\n5. Ən azı 8 UI testi yaz və hər testin hansı riski azaltdığını cədvəldə göstər.\n6. Testləri təmiz checkout-dan işə sal; real şəbəkədən və qeyri-sabit timer-lardan asılı olma.\n\n## 4. Konkret nümunə və izah\nTesti istifadəçi davranışı ilə yaz: “Boş motivasiya ilə Göndər basıldıqda xəta görünür, API çağırılmır”. Elementi label və ya button rolu ilə tap; səhifənin CSS class adını əsas meyar etmə.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, ən azı 8 UI testi, işlək test əmri və risk/test cədvəli. Testlər təmiz quraşdırmada stabil işləməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nSəkkiz testin risklə əlaqəsi yazılıb. Uğur, invalid input, loading, boş siyahı, retry və server xətası əhatə olunur; real internetə ehtiyac yoxdur.\n\n[[EN]]\n## 1. Goal\nProtect key behaviors in the application form and coordinator dashboard with tests.\n\n## 2. Before you start\nYour own frontend project, React Testing Library, and the test tool used by the project (Vitest/Jest). Continue an existing setup if available.\n\n## 3. Step-by-step work\n1. Continue your own repository.\n2. Choose the main successful flow and at least four error/edge cases.\n3. Find elements by label, role, and visible text rather than relying heavily on class names.\n4. Mock API requests and test loading, retry, invalid input, and server-error states.\n5. Write at least eight UI tests and explain the risk each test reduces.\n6. Run tests from a clean checkout without real-network dependencies or flaky timers.\n\n## 4. Concrete example and explanation\nTest user behavior: “Submitting empty motivation shows an error and makes no API call.” Locate by label or button role instead of relying on CSS class names.\n\n## 5. What to submit\nYour own GitHub repository link, at least eight UI tests, a working test command, and a risk/test table. Tests must run reliably in a clean setup.\n\n## 6. How to check your work\nMap eight tests to risks. Cover success, invalid input, loading, empty list, retry, and server failure without live internet.","new_description":"[[AZ]]\nComponent, user interaction və əsas error state-lər üçün etibarlı frontend testləri yaz.\n\nPulsuz alətlər: Visual Studio Code, Node.js (free), Vitest (open source). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nWrite reliable frontend tests for components, user interactions, and error states.\n\nFree tools: Visual Studio Code, Node.js (free), Vitest (open source). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Formda boş email, status badge, loading və xəta üçün avtomatik UI testləri yaz.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Vitest (open source)** — https://vitest.dev. UI və ya utility testlərini sintetik fixture-lərlə lokal işlət.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / frontend-engineering / task-8` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Vitest və Testing Library ilə sintetik fixture və sadə render testi qur. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. İstifadəçinin input yazması və submit etməsini simulyasiya et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Ən azı 6 test işə sal, test nəticəsini GitHub README-yə yaz. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Formda boş email, status badge, loading və xəta üçün avtomatik UI testləri yaz. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nFormda boş email, status badge, loading və xəta üçün avtomatik UI testləri yaz.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nMüraciət formu və koordinator dashboard-unda əsas istifadəçi davranışlarını testlərlə qoruyacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz frontend layihən, React Testing Library və layihədə istifadə olunan test aləti (Vitest/Jest). Mövcud test setup-u varsa, onu davam etdir.\n\n## 3. Addım-addım icra\n1. Öz repo-nu davam etdir.\n2. Əsas uğurlu axını və ən azı 4 xəta/kənar vəziyyəti seç.\n3. Elementləri label, role və görünən mətnlə tap; class adlarına həddindən artıq bağlanma.\n4. API sorğularını mock et və loading, retry, invalid input və server error hallarını yoxla.\n5. Ən azı 8 UI testi yaz və hər testin hansı riski azaltdığını cədvəldə göstər.\n6. Testləri təmiz checkout-dan işə sal; real şəbəkədən və qeyri-sabit timer-lardan asılı olma.\n\n## 4. Konkret nümunə və izah\nTesti istifadəçi davranışı ilə yaz: “Boş motivasiya ilə Göndər basıldıqda xəta görünür, API çağırılmır”. Elementi label və ya button rolu ilə tap; səhifənin CSS class adını əsas meyar etmə.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, ən azı 8 UI testi, işlək test əmri və risk/test cədvəli. Testlər təmiz quraşdırmada stabil işləməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nSəkkiz testin risklə əlaqəsi yazılıb. Uğur, invalid input, loading, boş siyahı, retry və server xətası əhatə olunur; real internetə ehtiyac yoxdur.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Write automated tests for invalid email, status badges, loading and error states.\n\n## Free tools and how to start\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Vitest (open source)** — https://vitest.dev. Run UI and utility tests against fictional fixtures locally.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / frontend-engineering / task-8` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Set up Vitest/Testing Library with deterministic fictional fixtures. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Simulate a user filling and submitting the form. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Run six tests and document the results. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Write automated tests for invalid email, status badges, loading and error states. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nWrite automated tests for invalid email, status badges, loading and error states.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nProtect key behaviors in the application form and coordinator dashboard with tests.\n\n## 2. Before you start\nYour own frontend project, React Testing Library, and the test tool used by the project (Vitest/Jest). Continue an existing setup if available.\n\n## 3. Step-by-step work\n1. Continue your own repository.\n2. Choose the main successful flow and at least four error/edge cases.\n3. Find elements by label, role, and visible text rather than relying heavily on class names.\n4. Mock API requests and test loading, retry, invalid input, and server-error states.\n5. Write at least eight UI tests and explain the risk each test reduces.\n6. Run tests from a clean checkout without real-network dependencies or flaky timers.\n\n## 4. Concrete example and explanation\nTest user behavior: “Submitting empty motivation shows an error and makes no API call.” Locate by label or button role instead of relying on CSS class names.\n\n## 5. What to submit\nYour own GitHub repository link, at least eight UI tests, a working test command, and a risk/test table. Tests must run reliably in a clean setup.\n\n## 6. How to check your work\nMap eight tests to risks. Cover success, invalid input, loading, empty list, retry, and server failure without live internet."},{"slug":"frontend-engineering","task_number":9,"title":"Code Review Fixes","old_description":"[[AZ]]\nCode review tapıntılarını istifadəçi təsiri üzrə prioritetləşdir və təhlükəsiz düzəlişlə bağla.\n\n[[EN]]\nPrioritize code-review findings by user impact and close them with safe fixes.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nFrontend kodunu review edib real səhvləri tapacaq, ən vacib olanlardan birini testlə birlikdə düzəldəcəksən. Şəxsi dizayn zövqünü bug kimi təqdim etmə.\n\n## 2. Başlamazdan əvvəl\nÖz layihəndə component, test və Git diff oxumaq. Pull request-in məqsədini və qəbul meyarlarını anlamaq vacibdir.\n\n## 3. Addım-addım icra\n1. Öz əvvəlki tapşırığındakı component və ya diff-i seç.\n2. Kodun məqsədini və qəbul meyarlarını oxu.\n3. Hər problem üçün təkrarlama addımı, fayl/component, istifadəçiyə təsir və ciddilik səviyyəsi yaz.\n4. 3–5 konkret tapıntı hazırla və təsirə görə sırala.\n5. Yüksək təsirli bir problemi düzəlt və regression test əlavə et.\n6. Testləri yenidən işə sal, qalan riskləri və yoxlama nəticəsini sənədləşdir.\n\n## 4. Konkret nümunə və izah\nTapıntı nümunəsi: “Sürətli filtr dəyişikliyində əvvəlki sorğu sonradan qayıdıb yeni siyahını əvəz edir”. Təkrarlama addımlarını yaz, düzəliş et və eyni vəziyyəti yaradan test əlavə et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 3–5 tapıntılı review hesabatı, bir düzəliş diff-i, regression test və qalan risk qeydi. Hər tapıntı konkret və təkrarlana bilən olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n3–5 sübutlu tapıntı təsirə görə sıralanıb. Bir vacib səhv üçün test əvvəl uğursuz, düzəlişdən sonra uğurludur; şəxsi zövq texniki səhv kimi yazılmayıb.\n\n[[EN]]\n## 1. Goal\nReview frontend code, identify real defects, and fix one high-impact issue with a test. Do not report personal design preference as a bug.\n\n## 2. Before you start\nHow to read components, tests, and Git diffs in your own project. Understand the pull request goal and acceptance criteria.\n\n## 3. Step-by-step work\n1. Choose a component or diff from your earlier task.\n2. Read the change goal and acceptance criteria.\n3. For each issue, record reproduction steps, file/component, user impact, and severity.\n4. Write three to five concrete findings and rank them by impact.\n5. Fix one high-impact issue and add a regression test.\n6. Rerun tests and document residual risks and retest results.\n\n## 4. Concrete example and explanation\nExample finding: “A slower previous filter request overwrites the latest list.” Record reproduction steps, fix the issue, and add a test recreating it.\n\n## 5. What to submit\nYour own GitHub repository link, a review report with three to five findings, one fix diff, a regression test, and a residual-risk note. Each finding must be specific and reproducible.\n\n## 6. How to check your work\nPrioritize 3–5 evidenced findings. For one important bug, show a failing test before the fix and passing after; separate taste from defects.","new_description":"[[AZ]]\nCode review tapıntılarını istifadəçi təsiri üzrə prioritetləşdir və təhlükəsiz düzəlişlə bağla.\n\nPulsuz alətlər: Visual Studio Code, GitHub Free, Vitest (open source). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nPrioritize code-review findings by user impact and close them with safe fixes.\n\nFree tools: Visual Studio Code, GitHub Free, Vitest (open source). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Code review zamanı tapılan 'mobil CTA gizlənir' problemini issue/test/fix ilə bağla.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n- **Vitest (open source)** — https://vitest.dev. UI və ya utility testlərini sintetik fixture-lərlə lokal işlət.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / frontend-engineering / task-9` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Üç müşahidə yaz, birini istifadəçi təsirinə görə prioritetləşdir. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Dəyişiklikdən əvvəl problem yaradan ekran ölçüsünü test et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Düzəliş commit-i və əvvəl/sonra test nəticəsini göstər. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Code review zamanı tapılan 'mobil CTA gizlənir' problemini issue/test/fix ilə bağla. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nCode review zamanı tapılan 'mobil CTA gizlənir' problemini issue/test/fix ilə bağla.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nFrontend kodunu review edib real səhvləri tapacaq, ən vacib olanlardan birini testlə birlikdə düzəldəcəksən. Şəxsi dizayn zövqünü bug kimi təqdim etmə.\n\n## 2. Başlamazdan əvvəl\nÖz layihəndə component, test və Git diff oxumaq. Pull request-in məqsədini və qəbul meyarlarını anlamaq vacibdir.\n\n## 3. Addım-addım icra\n1. Öz əvvəlki tapşırığındakı component və ya diff-i seç.\n2. Kodun məqsədini və qəbul meyarlarını oxu.\n3. Hər problem üçün təkrarlama addımı, fayl/component, istifadəçiyə təsir və ciddilik səviyyəsi yaz.\n4. 3–5 konkret tapıntı hazırla və təsirə görə sırala.\n5. Yüksək təsirli bir problemi düzəlt və regression test əlavə et.\n6. Testləri yenidən işə sal, qalan riskləri və yoxlama nəticəsini sənədləşdir.\n\n## 4. Konkret nümunə və izah\nTapıntı nümunəsi: “Sürətli filtr dəyişikliyində əvvəlki sorğu sonradan qayıdıb yeni siyahını əvəz edir”. Təkrarlama addımlarını yaz, düzəliş et və eyni vəziyyəti yaradan test əlavə et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 3–5 tapıntılı review hesabatı, bir düzəliş diff-i, regression test və qalan risk qeydi. Hər tapıntı konkret və təkrarlana bilən olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\n3–5 sübutlu tapıntı təsirə görə sıralanıb. Bir vacib səhv üçün test əvvəl uğursuz, düzəlişdən sonra uğurludur; şəxsi zövq texniki səhv kimi yazılmayıb.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Fix a review issue where a mobile CTA becomes hidden, with a regression test.\n\n## Free tools and how to start\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n- **Vitest (open source)** — https://vitest.dev. Run UI and utility tests against fictional fixtures locally.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / frontend-engineering / task-9` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Record three findings and prioritize one based on impact. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Reproduce the failing mobile viewport before editing. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Show the fix commit and a before/after regression check. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Fix a review issue where a mobile CTA becomes hidden, with a regression test. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nFix a review issue where a mobile CTA becomes hidden, with a regression test.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nReview frontend code, identify real defects, and fix one high-impact issue with a test. Do not report personal design preference as a bug.\n\n## 2. Before you start\nHow to read components, tests, and Git diffs in your own project. Understand the pull request goal and acceptance criteria.\n\n## 3. Step-by-step work\n1. Choose a component or diff from your earlier task.\n2. Read the change goal and acceptance criteria.\n3. For each issue, record reproduction steps, file/component, user impact, and severity.\n4. Write three to five concrete findings and rank them by impact.\n5. Fix one high-impact issue and add a regression test.\n6. Rerun tests and document residual risks and retest results.\n\n## 4. Concrete example and explanation\nExample finding: “A slower previous filter request overwrites the latest list.” Record reproduction steps, fix the issue, and add a test recreating it.\n\n## 5. What to submit\nYour own GitHub repository link, a review report with three to five findings, one fix diff, a regression test, and a residual-risk note. Each finding must be specific and reproducible.\n\n## 6. How to check your work\nPrioritize 3–5 evidenced findings. For one important bug, show a failing test before the fix and passing after; separate taste from defects."},{"slug":"frontend-engineering","task_number":10,"title":"Frontend Handoff","old_description":"[[AZ]]\nFrontend xüsusiyyətini developer və dizaynerə təhvil ver: setup, component, test və məhdudiyyətləri yaz.\n\n[[EN]]\nHand off a frontend feature with setup, component, test, and limitation details.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nBaşqa developer-in layihəni qura və dəyişə bilməsi üçün aydın təhvil sənədləri hazırlayacaqsan. Dizayner də əsas ekran vəziyyətlərini və responsive ölçüləri anlamalıdır.\n\n## 2. Başlamazdan əvvəl\nÖz frontend repo-n, README yazmaq, environment variable nümunəsi, komponent ağacı və test/build əmrləri. Production secret paylaşma.\n\n## 3. Addım-addım icra\n1. Əvvəlki tapşırıqlardakı öz layihəni davam etdir.\n2. Təmiz klondan quraşdırma, development server və test/build addımlarını README-yə yaz.\n3. Component tree, data flow, state keçidləri, breakpoint-lər və loading/empty/error vəziyyətlərini sənədləşdir.\n4. Environment nümunəsində yalnız dummy dəyərlər saxla; real açarları GitHub-a yükləmə.\n5. Mövcud test, lint və build əmrlərini işlət və nəticələri qeyd et.\n6. Screenshot-lar, məlum problemlər və növbəti 3 yaxşılaşdırma təklifini əlavə et.\n\n## 4. Konkret nümunə və izah\nREADME-ni yeni tələbənin izləyəcəyi ardıcıllıqla yaz: tələblər → clone → quraşdırma → işə salma → test/build → əsas ekranlar. `.env.example` varsa real açarlar əvəzinə izahlı nümunə dəyərlər qoy.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, README/feature guide, komponent və data-flow diaqramı, screenshot-lar, test/build nəticələri və məlum məhdudiyyətlər. Başqa developer fresh clone-dan təlimatla layihəni işə sala bilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nYeni qovluqdakı təmiz klon sənədlə işə düşür. Komponentlər/məlumat axını, ekran halları, yoxlama nəticələri və üç növbəti iş sənəddə tapılır.\n\n[[EN]]\n## 1. Goal\nPrepare clear handoff documentation so another developer can set up and modify your project. A designer should understand key states and responsive layouts.\n\n## 2. Before you start\nYour own frontend repository, README writing, environment-variable examples, component trees, and test/build commands. Never share production secrets.\n\n## 3. Step-by-step work\n1. Continue your own project from earlier tasks.\n2. Document setup from a clean clone, development server, and test/build steps in the README.\n3. Document the component tree, data flow, state transitions, breakpoints, and loading/empty/error states.\n4. Use dummy values only in environment examples; never push real keys to GitHub.\n5. Run available test, lint, and build commands and record the results.\n6. Add screenshots, known issues, and your next three improvement suggestions.\n\n## 4. Concrete example and explanation\nWrite the README in a newcomer’s order: prerequisites → clone → install → run → test/build → main screens. Use explanatory dummy values in `.env.example`.\n\n## 5. What to submit\nYour own GitHub repository link, README/feature guide, component and data-flow diagram, screenshots, test/build results, and known limitations. Another developer must be able to run the project from a fresh clone by following your instructions.\n\n## 6. How to check your work\nA clean clone runs using the documentation. Include component/data flow, screen states, verification results, and three next steps.","new_description":"[[AZ]]\nFrontend xüsusiyyətini developer və dizaynerə təhvil ver: setup, component, test və məhdudiyyətləri yaz.\n\nPulsuz alətlər: GitHub Free, Visual Studio Code, Node.js (free). Geniş bələdçi tapşırığın içindədir.\n\n[[EN]]\nHand off a frontend feature with setup, component, test, and limitation details.\n\nFree tools: GitHub Free, Visual Studio Code, Node.js (free). Find the detailed walkthrough inside the task.","new_instructions":"[[AZ]]\n## Tapşırığın sadə dildə izahı\nMəqsəd bu tapşırığı özün başa düşüb **praktiki işləyən nəticə** hazırlamaqdır. **Nümunə situasiya:** Yeni developer README ilə `npm install` → `npm run dev` → `npm test` işlədə bilsin.\n\n## Pulsuz proqramlar və onlardan istifadə\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n> Real istehsal məlumatı, ödənişli hosting və premium abunə tələb olunmur. Pulsuz limitlər dəyişə bilər; lokal test və sintetik məlumatdan istifadə et.\n\n## Addım-addım işləmə qaydası (8 mərhələ)\n1. Yalnız öz kompüterində `Talora / frontend-engineering / task-10` qovluğu aç; əvvəlki tapşırıqdakı sintetik məlumat və kodu götür.\n2. Bu işdə hansı problemi həll etdiyini, istifadəçini və yoxlanacaq nəticəni bir cümlə ilə yaz.\n3. Repo qovluqlarını və komponentlərin istifadə qaydasını izah et. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n4. Env.example, mock data, test və build əmrlərini sənədləşdir. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n5. Yeni klondan quraşdırma sınağı apar, açar/şifrə və real profil yükləmə. Qeyd və nəticəni fayl, kod, cədvəl, diaqram və ya ekran görüntüsü ilə sübut et.\n6. Praktik nümunəni yerinə yetir: Yeni developer README ilə `npm install` → `npm run dev` → `npm test` işlədə bilsin. Ən azı bir düzgün və bir boş/səhv hal üçün gözlənilən nəticəni qeyd et.\n7. Əvvəlki tapşırıq şərtlərində tələb olunan faylı və linki hazırla; mənbə faylı, test nəticəsi və qısa README əlavə et.\n8. Göndərməzdən əvvəl orijinal şərtlərin hər bəndini yoxla, 3–5 cümlədə nəyi öyrəndiyini və məhdudiyyətləri izah et.\n\n## İşlənmiş praktik nümunə\nYeni developer README ilə `npm install` → `npm run dev` → `npm test` işlədə bilsin.\nNümunəni öz layihənə uyğun dəyiş, gördüyün nəticəni nə ilə yoxladığını qeyd et. Demo rəqəmləri real statistikaya çevirmə.\n\n## Təhvil veriləcək materiallar\n- **Əsas iş:** aşağıdakı orijinal tapşırıqda tələb olunan fayl, GitHub repo və ya link.\n- **Mənbə və test:** redaktə edilə bilən fayllar, uyğun kod, sintetik data, ekran görüntüsü və ya test nəticəsi.\n- **İzah:** 3–5 cümləlik hesabat, istifadə edilmiş pulsuz alətlər və istinadlar.\n- **Təhlükəsizlik:** heç bir şifrə, API key, şəxsi müraciət məlumatı və ya icazəsiz material paylaşma.\n\n## 100 ballıq praktiki özünü qiymətləndirmə\n- **40 bal:** əsas fəaliyyətlər və rəsmi tələb olunan nəticələr hazırdır.\n- **25 bal:** nəticə işləyir, ölçülüb və mənfi hallar yoxlanıb.\n- **15 bal:** sənəd, fayl adları, README və təqdimat aydındır.\n- **10 bal:** təhlükəsizlik, mənbələr və pulsuz alət qaydalarına əməl olunub.\n- **10 bal:** seçimlərin səbəbi və növbəti təkmilləşdirmələr yazılıb.\n**Bu rubrik öyrənmə üçün nümunədir; əvvəldən qiymətləndirilmiş təqdimatları və rəsmi tapşırıq meyarlarını dəyişmir.**\n\n## Göndərməzdən əvvəl yoxla\n- Yalnız lokal, sintetik və ya istifadəsinə icazə verilmiş məlumat işlənib.\n- Paylaşım linki oxunur, fayl açılır, heç bir məxfi məlumat yoxdur.\n- Əvvəlki rəsmi şərtlərdə göstərilən nəticələr tamdır.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (dəyişməyib)\n## 1. Bu tapşırıq nə üçündür?\nBaşqa developer-in layihəni qura və dəyişə bilməsi üçün aydın təhvil sənədləri hazırlayacaqsan. Dizayner də əsas ekran vəziyyətlərini və responsive ölçüləri anlamalıdır.\n\n## 2. Başlamazdan əvvəl\nÖz frontend repo-n, README yazmaq, environment variable nümunəsi, komponent ağacı və test/build əmrləri. Production secret paylaşma.\n\n## 3. Addım-addım icra\n1. Əvvəlki tapşırıqlardakı öz layihəni davam etdir.\n2. Təmiz klondan quraşdırma, development server və test/build addımlarını README-yə yaz.\n3. Component tree, data flow, state keçidləri, breakpoint-lər və loading/empty/error vəziyyətlərini sənədləşdir.\n4. Environment nümunəsində yalnız dummy dəyərlər saxla; real açarları GitHub-a yükləmə.\n5. Mövcud test, lint və build əmrlərini işlət və nəticələri qeyd et.\n6. Screenshot-lar, məlum problemlər və növbəti 3 yaxşılaşdırma təklifini əlavə et.\n\n## 4. Konkret nümunə və izah\nREADME-ni yeni tələbənin izləyəcəyi ardıcıllıqla yaz: tələblər → clone → quraşdırma → işə salma → test/build → əsas ekranlar. `.env.example` varsa real açarlar əvəzinə izahlı nümunə dəyərlər qoy.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, README/feature guide, komponent və data-flow diaqramı, screenshot-lar, test/build nəticələri və məlum məhdudiyyətlər. Başqa developer fresh clone-dan təlimatla layihəni işə sala bilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nYeni qovluqdakı təmiz klon sənədlə işə düşür. Komponentlər/məlumat axını, ekran halları, yoxlama nəticələri və üç növbəti iş sənəddə tapılır.\n\n[[EN]]\n## Beginner explanation\nThe goal is to produce **a real, verifiable outcome** rather than theory alone. **Example scenario:** Enable a new developer to run npm install, npm run dev and npm test from README.\n\n## Free tools and how to start\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n> No production data, paid hosting or premium subscription is required. Free quotas may change; use local tests and fictional data.\n\n## Step-by-step procedure (8 stages)\n1. Create a local `Talora / frontend-engineering / task-10` folder and reuse earlier fictional data or source files.\n2. Summarize the user, the problem and a verifiable success criterion in one sentence.\n3. Document repository layout and component usage. Include evidence in a file, source code, sheet, diagram or screenshot.\n4. Include env.example, mock fixtures and build/test commands. Include evidence in a file, source code, sheet, diagram or screenshot.\n5. Test a clean setup and avoid publishing secrets or real user profiles. Include evidence in a file, source code, sheet, diagram or screenshot.\n6. Complete this worked example: Enable a new developer to run npm install, npm run dev and npm test from README. Note one valid and one invalid/empty case.\n7. Prepare the deliverable required by the original instructions with editable sources, tests and a short README.\n8. Before submitting, check the original criteria and write a three-to-five sentence conclusion and limitations.\n\n## Practical worked example\nEnable a new developer to run npm install, npm run dev and npm test from README.\nAdapt the example to your own project, verify the result and do not present fictional statistics as real.\n\n## Required submission\n- **Main result:** the file, repository or link required by the unchanged original assignment below.\n- **Source and tests:** editable materials, appropriate code, fictional data, screenshots or test evidence.\n- **Explanation:** three to five sentences on findings, free tools and citations.\n- **Safety:** no passwords, API keys, private applications or unlicensed content.\n\n## Self-assessment rubric (100 points)\n- **40:** complete core actions and original deliverables.\n- **25:** measured, working result and invalid-case testing.\n- **15:** readable files, README and structure.\n- **10:** security, citations and free tools.\n- **10:** clear reasoning and suggested next steps.\n**Illustrative learning rubric only: it does not change official criteria or previously graded work.**\n\n## Before submission\n- Use local, fictional or properly authorized data.\n- Check links, exports and absence of confidential information.\n- Verify all original official requirements below.\n\n## Original official requirements (unchanged)\n## 1. Goal\nPrepare clear handoff documentation so another developer can set up and modify your project. A designer should understand key states and responsive layouts.\n\n## 2. Before you start\nYour own frontend repository, README writing, environment-variable examples, component trees, and test/build commands. Never share production secrets.\n\n## 3. Step-by-step work\n1. Continue your own project from earlier tasks.\n2. Document setup from a clean clone, development server, and test/build steps in the README.\n3. Document the component tree, data flow, state transitions, breakpoints, and loading/empty/error states.\n4. Use dummy values only in environment examples; never push real keys to GitHub.\n5. Run available test, lint, and build commands and record the results.\n6. Add screenshots, known issues, and your next three improvement suggestions.\n\n## 4. Concrete example and explanation\nWrite the README in a newcomer’s order: prerequisites → clone → install → run → test/build → main screens. Use explanatory dummy values in `.env.example`.\n\n## 5. What to submit\nYour own GitHub repository link, README/feature guide, component and data-flow diagram, screenshots, test/build results, and known limitations. Another developer must be able to run the project from a fresh clone by following your instructions.\n\n## 6. How to check your work\nA clean clone runs using the documentation. Include component/data flow, screen states, verification results, and three next steps."}]$legacy_payload$::jsonb);
DO $preflight$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='frontend-engineering' AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions'
 AND t.description=e.item->>'old_description' AND t.status='published' AND t.is_required;
 IF (SELECT jsonb_array_length(payload) FROM legacy_guides)<>10 OR n<>10 THEN RAISE EXCEPTION 'Version mismatch: frontend-engineering: %',n; END IF;
END; $preflight$;
DO $apply$
DECLARE n integer;
BEGIN
 UPDATE public.internship_tasks t SET instructions=e.item->>'new_instructions',description=e.item->>'new_description'
 FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 WHERE i.slug='frontend-engineering' AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions' AND t.description=e.item->>'old_description';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>10 THEN RAISE EXCEPTION 'Expected 10 updates for frontend-engineering, got %',n; END IF;
END; $apply$;
DO $verify$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='frontend-engineering' AND t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required;
 IF n<>10 THEN RAISE EXCEPTION 'Post-update mismatch: frontend-engineering: %',n; END IF;
END; $verify$;
COMMIT;
